class ExpressionEvaluator:
    def __init__(self, expr):
        self.expr = expr.replace(" ", "")
        self.pos = 0
        self.current_char = self.expr[self.pos] if self.expr else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.pos += 1
        self.current_char = self.expr[self.pos] if self.pos < len(self.expr) else None

    def parse_number(self):
        num_str = ''
        while self.current_char and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def parse_parentheses(self):
        self.advance()  # skip '('
        result = self.parse_expression()
        self.advance()  # skip ')'
        return result

    def parse_factor(self):
        if self.current_char.isdigit() or (self.current_char and self.current_char == '.'):
            return self.parse_number()
        elif self.current_char == '(':
            return self.parse_parentheses()
        self.error()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.parse_factor()
            elif op == '/':
                result /= self.parse_factor()
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.parse_term()
            elif op == '-':
                result -= self.parse_term()
        return result

