class Parser:
    def __init__(self, expression):
        self.expression = expression.replace(' ', '')
        self.pos = 0
        self.current_char = self.expression[self.pos] if self.expression else None

    def error(self):
        raise Exception("Invalid expression")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expression):
            self.current_char = self.expression[self.pos]
        else:
            self.current_char = None

    def factor(self):
        if self.current_char.isdigit() or self.current_char == '.':
            start = self.pos
            while self.current_char and (self.current_char.isdigit() or self.current_char == '.'):
                self.advance()
            return float(self.expression[start:self.pos])
        elif self.current_char == '(':
            self.advance()
            result = self.expr()
            if self.current_char == ')':
                self.advance()
                return result
            else:
                self.error()

    def term(self):
        result = self.factor()
        while self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.factor()
            elif self.current_char == '/':
                self.advance()
                denominator = self.factor()
                if denominator == 0:
                    self.error()
                result /= denominator
        return result

    def expr(self):
        result = self.term()
        while self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.term()
            elif self.current_char == '-':
                self.advance()
                result -= self.term()
        return result

