class Evaluator:
    def __init__(self, expression):
        self.expression = expression.replace(" ", "")
        self.index = 0

    def parse(self):
        self.index = 0
        return self.expression_evaluation()

    def expression_evaluation(self):
        result = self.term()
        while self.index < len(self.expression):
            if self.current_char() in ('+', '-'):
                op = self.current_char()
                self.index += 1
                if op == '+':
                    result += self.term()
                elif op == '-':
                    result -= self.term()
            else:
                break
        return result

    def term(self):
        result = self.factor()
        while self.index < len(self.expression):
            if self.current_char() in ('*', '/'):
                op = self.current_char()
                self.index += 1
                if op == '*':
                    result *= self.factor()
                elif op == '/':
                    divisor = self.factor()
                    if divisor != 0:
                        result /= divisor
                    else:
                        raise ZeroDivisionError("division by zero")
            else:
                break
        return result

    def factor(self):
        if self.current_char() == '(':
            self.index += 1
            result = self.expression_evaluation()
            if self.current_char() == ')':
                self.index += 1
                return result
            else:
                raise SyntaxError("mismatched parentheses")
        else:
            start_index = self.index
            while (self.index < len(self.expression) and
                   self.current_char().isdigit() or 
                   self.current_char() == '.'):
                self.index += 1
            if start_index == self.index:
                raise SyntaxError("invalid syntax")
            return float(self.expression[start_index:self.index])

    def current_char(self):
        if self.index < len(self.expression):
            return self.expression[self.index]
        return None


