class Calculator:
    def __init__(self, expression: str):
        self.expression = expression
        self.current_index = 0

    def parse(self) -> float:
        self.current_index = 0
        return self.evaluate_expression()

    def evaluate_expression(self) -> float:
        total = self.evaluate_term()
        while self.current_index < len(self.expression):
            char = self.peek()
            if char in ('+', '-'):
                self.current_index += 1
                if char == '+':
                    total += self.evaluate_term()
                elif char == '-':
                    total -= self.evaluate_term()
            else:
                break
        return total

    def evaluate_term(self) -> float:
        total = self.evaluate_factor()
        while self.current_index < len(self.expression):
            char = self.peek()
            if char in ('*', '/'):
                self.current_index += 1
                if char == '*':
                    total *= self.evaluate_factor()
                elif char == '/':
                    total /= self.evaluate_factor()
            else:
                break
        return total

    def evaluate_factor(self) -> float:
        char = self.peek()
        if char.isdigit() or char == '.':
            return self.evaluate_number()
        elif char == '(':
            self.current_index += 1
            total = self.evaluate_expression()
            self.current_index += 1  # Skip past ')'
            return total
        raise ValueError("Invalid character encountered: {}".format(char))

    def evaluate_number(self) -> float:
        start_index = self.current_index
        while (self.current_index < len(self.expression) and
               (self.peek().isdigit() or self.peek() == '.')):
            self.current_index += 1
        return float(self.expression[start_index:self.current_index])

    def peek(self) -> str:
        return self.expression[self.current_index] if self.current_index < len(self.expression) else ''

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression respecting operator precedence using a recursive descent parser.
    """
    calculator = Calculator(expr.replace(" ", ""))
    return calculator.parse()
